import{c as r,Q as t,j as i,m as a}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"MeshCoreNG","description":"","frontmatter":{},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md"}'),s={name:"docs/index.md"};function o(n,e,l,h,d,c){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="meshcoreng" tabindex="-1">MeshCoreNG <a class="header-anchor" href="#meshcoreng" aria-label="Permalink to &quot;MeshCoreNG&quot;">​</a></h1><p>MeshCoreNG is a Next Gen variant of MeshCore. It builds on the existing firmware and protocol to make repeaters smarter in dense networks — without breaking compatibility with existing clients.</p><h2 id="what-is-different-from-meshcore" tabindex="-1">What is different from MeshCore? <a class="header-anchor" href="#what-is-different-from-meshcore" aria-label="Permalink to &quot;What is different from MeshCore?&quot;">​</a></h2><p>MeshCoreNG adds:</p><ul><li><strong>Dense-mesh controls</strong> — tune how aggressively repeaters forward flood adverts.</li><li><strong>Dense stats</strong> — real-time network telemetry per repeater.</li><li><strong>Internet bridge</strong> — link remote LoRa islands over TCP.</li><li><strong>USB bridge</strong> — connect repeaters without WiFi via a USB relay script.</li><li><strong>Better channel detection</strong> — hardware CAD scan before transmitting.</li><li><strong>Power saving</strong> — configurable sleep with transparent controls.</li></ul><p>Everything else stays the same. Existing MeshCore clients, apps and firmware keep working.</p><h2 id="quick-links" tabindex="-1">Quick links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick links&quot;">​</a></h2><ul><li><a href="/docs/getting-started.html">Getting started</a></li><li><a href="/docs/dense-mesh.html">Dense mesh</a></li><li><a href="/docs/bridge.html">Internet bridge</a></li><li><a href="/docs/power-saving.html">Power saving</a></li><li><a href="/docs/cli.html">CLI reference</a></li><li><a href="/flasher/">Flash firmware</a></li><li><a href="https://github.com/MichTronics/MeshCoreNG" target="_blank" rel="noreferrer">GitHub repository</a></li><li><a href="https://docs.meshcore.io" target="_blank" rel="noreferrer">MeshCore upstream docs</a></li></ul>',8)])])}const g=r(s,[["render",o]]);export{m as __pageData,g as default};
